mapper.select:
SELECT p.id, p.customer_id, p.version_id, v.name AS version_name, s.inbound_price, s.one_price, p.spec, p.authorized_price FROM zc_customer_version_spec_price p LEFT JOIN zc_product_version_spc s ON s.version_id = p.version_id AND s.spec = p.spec AND s.deleted = 0 LEFT JOIN zc_product_version v ON v.id = p.version_id AND v.deleted = 0 WHERE p.deleted = 0 AND p.customer_id = #{customerId}
AND p.version_id = #{versionId}
ORDER BY p.version_id, p.spec
